"""Render the second-round concept briefs into the existing local gallery."""
from pathlib import Path
import html,json
root=Path(__file__).resolve().parent.parent
out=root/'design-tech'
files=sorted((out/'briefs').glob('*.json'))
if len(files)!=5: raise SystemExit(f'Waiting for five briefs: {len(files)} present')
items=[json.loads(p.read_text()) for p in files]
required=['id','title','oneLiner','targetFeeling','gesture','magicMoment','example','must','nonGoals','demo','buildHours','risk','fallback','verdict','sources']
for item in items:
    missing=set(required)-set(item)
    if missing: raise SystemExit(f"Missing keys in {item.get('id')}: {sorted(missing)}")
H=html.escape
arts=[
'<rect x="28" y="24" width="320" height="215" rx="13" fill="#f7f4e9" stroke="#242721" stroke-width="3"/><path d="M28 53h320" stroke="#242721" stroke-width="2"/><circle cx="45" cy="40" r="4" fill="#e57251"/><circle cx="60" cy="40" r="4" fill="#e5b455"/><path d="M58 91h181m-181 17h242m-242 17h200m-200 49h188m-188 17h240m-240 17h159" stroke="#bcc2b7" stroke-width="7"/><rect x="52" y="160" width="235" height="38" fill="#c6fa86" opacity=".8"/><circle cx="312" cy="179" r="22" fill="#435be8"/><circle cx="306" cy="174" r="3" fill="#fff"/><circle cx="318" cy="174" r="3" fill="#fff"/><path d="M308 186q5 4 10-1" stroke="#fff" fill="none" stroke-width="2"/><path d="M312 146q-18-66-76-63" stroke="#435be8" stroke-dasharray="4 5" fill="none"/>',
'<rect x="28" y="24" width="320" height="215" rx="13" fill="#252824"/><text x="55" y="95" font-family="Georgia" font-style="italic" font-size="35" fill="#efe5c9">Maison</text><path d="M54 115h235m-235 18h176" stroke="#73766a" stroke-width="4"/><path d="M348 24v215H165z" fill="#b5c8fb"/><path d="M165 239l78-125 34 93z" fill="#e7edff"/><rect x="224" y="145" width="98" height="35" rx="4" fill="#334ee0"/><text x="238" y="167" font-size="13" fill="#fff">Book a table</text><path d="M315 220q18-41 17-62" stroke="#273ccc" stroke-width="3" fill="none"/>',
'<path d="M61 58h115v68H61z" fill="#e8c9ed" transform="rotate(-9 119 90)"/><text x="78" y="100" font-family="Georgia" font-size="19" fill="#423948">Lost in light</text><rect x="213" y="75" width="108" height="112" fill="#d4e8b3" transform="rotate(9 267 132)"/><circle cx="265" cy="121" r="24" fill="#8fac66"/><path d="M177 97q30-21 35 25" stroke="#4535af" fill="none" stroke-width="3" stroke-dasharray="5 5"/><rect x="88" y="182" width="208" height="53" fill="#fcf8ed" stroke="#4535af" stroke-width="2"/><text x="111" y="214" font-size="19" font-family="Georgia" fill="#4535af">A little borrowed world.</text><path d="M177 135l-10 33m85-13-22 19" stroke="#4535af" stroke-width="2"/>',
'<rect x="31" y="27" width="315" height="210" rx="12" fill="#243d36"/><text x="56" y="83" font-size="30" font-weight="800" fill="#c5ed85">A PAGE SINGS.</text><path d="M57 108h233m-233 16h177m-177 16h212" stroke="#6f9082" stroke-width="5"/><path d="M58 202v-28m18 28v-45m18 45v-33m18 33v-55m18 55v-18m18 18v-38m18 38v-62m18 62v-26m18 26v-42m18 42v-32m18 32v-16m18 16v-51m18 51v-28" stroke="#c5ed85" stroke-width="7"/><path d="M39 152q128-54 294 5" stroke="#f0b185" stroke-width="3" fill="none"/>',
'<path d="M55 170C27 43 301 14 285 110S95 251 142 103S355 144 284 204" fill="none" stroke="#e87852" stroke-width="5"/><path d="M76 198C25 94 294 24 278 120S125 232 161 90S334 170 265 226" fill="none" stroke="#6876e7" stroke-width="4" stroke-dasharray="7 5"/><path d="M179 64l7 30 9-12 15-3z" fill="#6876e7"/><path d="M54 149l7 30 9-12 15-3z" fill="#e87852"/><circle cx="226" cy="175" r="19" fill="none" stroke="#e8b850" stroke-width="3"/><circle cx="226" cy="175" r="28" fill="none" stroke="#e8b850" stroke-width="1"/>'
]
colors=['#e1e8fc','#e6e9dd','#e9dcf0','#e1e8c8','#f0dfd5']
badges=['Closest to your dots idea','Most distinctive website gesture','Best for making things','Most sensory','Strongest playful experiment']
def bullets(values):return '<ul>'+''.join('<li>'+H(str(v))+'</li>' for v in values)+'</ul>'
cards=[]
for i,d in enumerate(items):
    demo=''.join(f'<tr><td>{H(x["seconds"])}</td><td>{H(x["action"])}</td></tr>' for x in d['demo'])
    sources=''.join(f'<li><a href="{H(s["url"],quote=True)}" target="_blank" rel="noopener">{H(s["title"])}</a> — {H(s["takeaway"])}</li>' for s in d['sources'])
    cards.append(f'''<article id="{d['id']}"><div class="left"><div class="art" style="background:{colors[i]}"><span class="num">0{i+1}</span><svg viewBox="0 0 380 265" role="img" aria-label="{H(d['title'])} interaction sketch">{arts[i]}</svg></div><div class="label">{badges[i]}</div><h2>{H(d['title'])}</h2><p class="lead">{H(d['oneLiner'])}</p><p class="feeling">Target feeling: <strong>{H(d['targetFeeling'])}</strong></p><div class="gesture">{H(d['gesture'])}</div></div><div class="right"><h3>The moment worth showing</h3><p>{H(d['magicMoment'])}</p><ol class="beats">{''.join('<li>'+H(x)+'</li>' for x in d['example'])}</ol><h3>Demo MVP · {d['buildHours']} focused hours</h3>{bullets(d['must'])}<details><summary>Demo route, cuts & references</summary><table><tbody>{demo}</tbody></table><h3>Outside this build</h3>{bullets(d['nonGoals'])}<p><b>Hardest part:</b> {H(d['risk'])}</p><p><b>Fallback:</b> {H(d['fallback'])}</p><p>{H(d['verdict'])}</p><ul class="sources">{sources}</ul></details><a class="brief" href="briefs/{d['id']}.md">Read the full brief ↗</a></div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Design × Tech — Five ways to touch a browser</title><style>
:root{color:#222720;background:#f5f3ea;font-family:Arial,Helvetica,sans-serif}*{box-sizing:border-box}body{margin:0}a{color:inherit;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #465bd8;outline-offset:5px}header{padding:22px 5vw;border-bottom:1px solid #222720;display:flex;justify-content:space-between;font-size:12px;gap:20px}nav{display:flex;gap:24px;flex-wrap:wrap}.hero{padding:65px 7vw 45px;max-width:1450px;margin:auto;display:grid;grid-template-columns:1.7fr 1fr;gap:55px;align-items:end}.eyebrow,.label,.gesture{font:11px 'Courier New',monospace;letter-spacing:1px;text-transform:uppercase}h1{font-size:clamp(58px,6.5vw,102px);line-height:.98;letter-spacing:-.07em;margin:20px 0}h1 em{color:#465bd8;font-family:Georgia,serif;font-weight:400}.hero p{font-size:18px;line-height:1.5}.hero .small{font-size:12px;color:#62685d}.jump{display:flex;gap:9px;flex-wrap:wrap;padding:22px 7vw;border-block:1px solid #c9cdc2;background:#e3e9d5}.jump a{padding:10px 17px;border:1px solid #647057;border-radius:30px;text-decoration:none;font-size:13px}.jump a:hover{background:#f5f3ea}main{max-width:1390px;margin:auto;padding:0 7vw}article{padding:55px 0;border-bottom:1px solid #bfc4b7;display:grid;grid-template-columns:1fr 1.15fr;gap:55px;scroll-margin-top:20px}.art{border-radius:4px;position:relative;border:1px solid #aeb7a7}.art svg{display:block;width:100%;height:auto}.num{position:absolute;top:12px;right:15px;font:12px monospace}.label{margin-top:25px;color:#465bd8;font-weight:bold}h2{font-size:42px;letter-spacing:-1.8px;line-height:1.05;margin:13px 0}.lead{font-family:Georgia,serif;font-size:23px;line-height:1.4}.feeling{font-size:14px;line-height:1.55}.gesture{padding-top:16px;border-top:1px solid #c9cdc2;line-height:1.7}h3{font-size:14px;letter-spacing:.3px;margin:3px 0 15px}.right p,.right li{font-size:15px;line-height:1.65}.right ul,.beats{padding-left:20px}.right li{padding-left:5px;margin-bottom:9px}.beats{padding-bottom:12px;margin-bottom:24px;border-bottom:1px solid #d2d6cc}details{padding:20px 0;border-top:1px solid #c9cdc2;margin-top:22px}summary{font-size:14px;font-weight:bold;cursor:pointer}.brief{font-size:13px;display:inline-block;margin-top:12px}table{margin:20px 0;border-collapse:collapse;width:100%;font-size:13px}td{padding:10px;border-bottom:1px solid #d5d8ce;vertical-align:top;line-height:1.5}td:first-child{white-space:nowrap;font-family:monospace}.sources li{font-size:12px}.decision{padding:55px 0;display:grid;grid-template-columns:1fr 1fr;gap:55px}.decision h2{font-size:31px}.decision p{font-size:15px;line-height:1.65}.decision .note{padding:20px;background:#e1e8fc;border-radius:3px}footer{padding:25px 7vw;border-top:1px solid #222720;font-size:12px;display:flex;justify-content:space-between;gap:20px}@media(max-width:750px){header{font-size:10px;align-items:start}nav{gap:10px}.hero{padding-top:35px;grid-template-columns:1fr;gap:10px}h1{font-size:62px}.hero p{font-size:16px}.jump{padding:15px 7vw}.jump a{font-size:11px;padding:8px 10px}article{grid-template-columns:1fr;gap:30px;padding-block:35px}.art{max-width:500px}h2{font-size:37px}.lead{font-size:21px}.decision{grid-template-columns:1fr;gap:20px}footer{display:block;line-height:1.9}}
</style></head><body><header><b>COMMON GROUND / DESIGN × TECH</b><nav><a href="../index.html">Earlier sketches</a><a href="FEASIBILITY.md">Dots + Gmail feasibility</a><a href="README.md">Recommendation</a></nav></header><section class="hero"><div><div class="eyebrow">Second exploration · five concept briefs</div><h1>What if the web<br>felt <em>different?</em></h1></div><div><p>A companion you can place. A page you can peel. Words you can pick up. A website you can play. Your past cursor, playing beside you.</p><p class="small">Developed by five GPT-6.1 Sol agents at xhigh reasoning. These are idea and MVP briefs; the illustrations describe proposed interactions. No new prototypes are claimed.</p></div></section><nav class="jump" aria-label="Jump to an idea">JUMPS</nav><main>CARDS<section class="decision"><div><div class="eyebrow">My recommendation</div><h2>Start with Dot.<br>Give it a physical verb.</h2><p>Drag it onto something. Let it lead you to evidence. Pin it as a note. The character's relationship with the page is the design.</p><p>If you want a more playful departure, try Cursor Choir: a duet with your own past gestures. Peel has the strongest website-transformation moment, with a tighter supported-page boundary.</p><a href="README.md">Read the comparison ↗</a></div><div class="note"><h2>And Gmail?</h2><p>A single authorised test account is technically plausible. OAuth setup and restricted mailbox scopes make it a stretch feature for this day. Page notes and on-page questions give Dot a complete demonstration without it.</p><p>For a restaurant, show the booking doorway and the actual policy text. A completed reservation across arbitrary providers is a separate build.</p><a href="FEASIBILITY.md">Verified capabilities and exact cuts ↗</a></div></section></main><footer><span>ONE SETTING · ONE GESTURE · ONE MEMORABLE CONSEQUENCE</span><span>Briefs and build targets · Commercial viability is not the objective</span></footer></body></html>'''
jumps=''.join(f'<a href="#{d["id"]}">0{i+1} {H(d["title"])}</a>' for i,d in enumerate(items))
(out/'index.html').write_text(page.replace('JUMPS',jumps).replace('CARDS','\n'.join(cards)))
(out/'concepts.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print('Rendered five Design × Tech briefs')
